<script setup lang="ts">
import {onMounted,ref,watch} from 'vue'
import {WorkforceApiError} from '../api'
import {usePhasePage} from '../phasePage'
import {clonePolicy,copyPolicyYear,draftFromTemplate,statutoryPolicyValid,validPolicyYear,useStatutoryText} from '../statutoryPolicy'
import type {StatutoryPolicy,StatutoryTemplate} from '../statutoryPolicy'
import StatutoryPolicyEditor from '../components/StatutoryPolicyEditor.vue'
import PhaseStatus from '../components/PhaseStatus.vue'
const {api,home,t,loading,busy,failure,notice,load,write}=usePhasePage(),{s}=useStatutoryText()
const items=ref<StatutoryPolicy[]>([]),draft=ref<StatutoryPolicy|null>(null),history=ref<StatutoryPolicy[]>([]),targetYear=ref(new Date().getFullYear()),reviewed=ref(false),historical=ref(false),authorized=ref(false)
watch(draft,()=>{reviewed.value=false},{deep:true,flush:'sync'})
function edit(policy:StatutoryPolicy,readonly=false){draft.value=clonePolicy(policy);historical.value=readonly;reviewed.value=false;notice.value='';failure.value='';if(!readonly)history.value=[]}
function refresh(){if(!home.value?.headOffice)return;void load(()=>api().get<{items:StatutoryPolicy[];headOffice:boolean}>('/statutory-policies'),v=>{authorized.value=v.headOffice;if(!v.headOffice){items.value=[];draft.value=null;failure.value=s('noAccess');return}items.value=v.items;const selected=v.items.find(p=>p.id===draft.value?.id);if(selected)edit(selected)})}
function template(){if(!authorized.value)return;if(!validPolicyYear(targetYear.value)){failure.value=s('invalid');return}void load(()=>api().get<StatutoryTemplate>('/statutory-policy-templates/'+targetYear.value),v=>{edit(draftFromTemplate(v));notice.value=s('draftHint')})}
function loadCdac(){if(!authorized.value||!draft.value||historical.value||!validPolicyYear(draft.value.year))return;const selected=draft.value.id,year=draft.value.year;void load(()=>api().get<StatutoryTemplate>('/statutory-policy-templates/'+year),v=>{if(draft.value?.id===selected&&v.config.cdac){const cdac=clonePolicy(v.config.cdac);cdac.effectiveFrom=draft.value.effectiveFrom;cdac.effectiveTo=draft.value.effectiveTo;draft.value.config.cdac=cdac;notice.value=s('draftHint')}})}
function copyYear(){if(!authorized.value)return;if(!draft.value||!validPolicyYear(targetYear.value)){failure.value=s('invalid');return}edit(copyPolicyYear(draft.value,targetYear.value));notice.value=s('draftHint')}
function versions(){if(!draft.value?.version)return;const id=draft.value.id;void load(()=>api().get<StatutoryPolicy[]>('/statutory-policies/'+encodeURIComponent(id)+'/versions'),v=>history.value=v)}
function currentVersion(){const current=items.value.find(p=>p.id===draft.value?.id);if(current)edit(current)}
async function save(){if(!authorized.value||!home.value?.headOffice||!draft.value||historical.value||!reviewed.value||busy.value)return;if(!statutoryPolicyValid(draft.value,items.value)){failure.value=s('invalid');return}const value=clonePolicy(draft.value),{id,version,...body}=value;let saved:StatutoryPolicy|null=null,policyError='';await write(async()=>{try{saved=await api().put<StatutoryPolicy>('/statutory-policies/'+encodeURIComponent(id),{...body,expectedVersion:version})}catch(e){if(e instanceof WorkforceApiError){if(e.code==='WORKFORCE_STATUTORY_OVERLAP')policyError=s('overlap');else if(e.code==='WORKFORCE_CONFLICT')policyError=s('conflict');else if(e.code==='WORKFORCE_INVALID')policyError=s('invalid')}throw e}},()=>{if(!saved)return;const index=items.value.findIndex(p=>p.id===id);if(index<0)items.value.push(saved);else items.value[index]=saved;edit(saved);notice.value=s('saved')});if(policyError&&failure.value)failure.value=policyError}
onMounted(refresh)
</script>
<template><section v-if="home?.headOffice" class="wf-panel statutory-policy-page"><header class="wf-toolbar"><h2>{{s('title')}}</h2><button type="button" :disabled="loading||busy" @click="refresh">{{s('reload')}}</button></header><p class="wf-hint">{{s('hint')}}</p><p class="wf-hint">{{s('templateYears')}}</p><PhaseStatus :loading="loading" :failure="failure"/><p v-if="notice" role="status">{{notice}}</p><fieldset :disabled="busy||loading||!authorized"><legend>{{s('select')}}</legend><div class="wf-filters"><label>{{s('select')}}<select :value="historical?'':draft?.id||''" @change="edit(items.find(p=>p.id===($event.target as HTMLSelectElement).value)!)"><option value="" disabled>{{s('select')}}</option><option v-for="p in items" :key="p.id" :value="p.id">{{p.year}} · {{p.name}} · v{{p.version}} · {{s(p.enabled?'enabled':'draft')}}</option></select></label><label>{{s('year')}}<input v-model.number="targetYear" type="number" min="2000" max="2100" required></label><button type="button" @click="template">{{s('template')}}</button><button type="button" :disabled="!draft" @click="copyYear">{{s('copy')}}</button></div></fieldset><p v-if="!items.length&&!loading" class="wf-hint">{{s('empty')}}</p><form v-if="draft" @submit.prevent="save"><fieldset :disabled="busy||loading||historical"><legend>{{draft.name}} · v{{draft.version}}</legend><div class="wf-filters"><label>{{s('name')}}<input v-model="draft.name" required maxlength="120"></label><label>{{s('year')}}<input v-model.number="draft.year" required type="number" min="2000" max="2100" @change="reviewed=false"></label><label>{{s('currency')}}<input :value="draft.currency" readonly></label><label>{{s('from')}}<input v-model="draft.effectiveFrom" required type="date"></label><label>{{s('to')}}<input v-model="draft.effectiveTo" required type="date"></label><label class="wf-check"><input v-model="draft.enabled" type="checkbox">{{s('enabled')}}</label></div><StatutoryPolicyEditor :config="draft.config" :disabled="busy||loading||historical" @load-cdac="loadCdac"/><div class="wf-form-actions"><label class="wf-check"><input v-model="reviewed" type="checkbox">{{s('review')}}</label><button type="submit" class="primary" :disabled="!reviewed||busy||historical">{{s('save')}}</button></div></fieldset></form><template v-if="draft?.version"><div class="wf-form-actions"><button type="button" :disabled="busy||loading" @click="versions">{{s('history')}}</button><button v-if="historical" type="button" :disabled="busy||loading" @click="currentVersion">{{s('edit')}}</button></div><p v-if="historical" role="status">{{s('readonly')}}</p><div v-if="history.length" class="wf-table-wrap"><table><thead><tr><th>{{s('version')}}</th><th>{{s('name')}}</th><th>{{s('from')}}</th><th>{{s('to')}}</th><th></th></tr></thead><tbody><tr v-for="p in history" :key="p.version"><td>{{p.version}}</td><td>{{p.name}}</td><td>{{p.effectiveFrom}}</td><td>{{p.effectiveTo}}</td><td><button type="button" :disabled="busy||loading" @click="edit(p,true)">{{s('view')}}</button></td></tr></tbody></table></div></template></section><p v-else role="alert">{{s('noAccess')}}</p></template>
<style scoped>.statutory-policy-page>fieldset,.statutory-policy-page form>fieldset{min-width:0;border:1px solid #e0e7ed;padding:12px;margin:10px 0}.statutory-policy-page .wf-filters{align-items:end}.statutory-policy-page label{font-size:12px}.statutory-policy-page .wf-form-actions{flex-wrap:wrap}</style>
